Here is a production-ready, idiomatic Terraform refactoring that consolidates duplicated `dev`/`prod` blocks into a single parameterized module using `for_each`, with explicit zero-diff state migration steps.

### 📁 Directory Structure
```
├── main.tf
├── variables.tf
├── dev.tfvars
├── prod.tfvars
├── modules/
│   └── environment/
│       └── main.tf
└── secrets/
    └── db_connection.sops.yaml  # SOPS-encrypted (never committed in plaintext)
```

### 🌍 Root Configuration (`main.tf`)
```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws  = { source = "hashicorp/aws", version = "~> 5.0" }
    sops = { source = "carlpett/sops", version = "~> 0.4" }
  }
}

variable "environments" {
  type = map(object({
    region             = string
    eks_node_count     = number
    eks_instance_type  = string
    rds_instance_class = string
    rds_multi_az       = bool
    rds_encrypted      = bool
    s3_enable_crr      = bool
    iam_use_oidc       = bool
    https_use_cf       = bool
  }))
  default = {}
}

# Multi-region provider aliases (required for dev/prod in different regions)
provider "aws" { alias = "dev" }
provider "aws" { alias = "prod" }

module "app_environments" {
  source   = "./modules/environment"
  for_each = var.environments

  env_name           = each.key
  region             = each.value.region
  eks_node_count     = each.value.eks_node_count
  eks_instance_type  = each.value.eks_instance_type
  rds_instance_class = each.value.rds_instance_class
  rds_multi_az       = each.value.rds_multi_az
  rds_encrypted      = each.value.rds_encrypted
  s3_enable_crr      = each.value.s3_enable_crr
  iam_use_oidc       = each.value.iam_use_oidc
  https_use_cf       = each.value.https_use_cf
  db_secret          = data.sops_file.db_secret.value # Decrypted at runtime

  # Shared infrastructure references
  vpc_id             = data.aws_vpc.shared.id
  private_subnet_ids = data.aws_subnets.private.ids
  cluster_role_arn   = aws_iam_role.eks_cluster.arn
  node_role_arn      = aws_iam_role.eks_node.arn
  acm_arn            = aws_acm_certificate.app.arn

  # Provider override per environment
  providers = {
    aws = each.key == "dev" ? aws.dev : aws.prod
  }
}

data "sops_file" "db_secret" {
  source_file = "${path.module}/secrets/db_connection.sops.yaml"
}
```

### ⚙️ Environment Configs (`dev.tfvars` / `prod.tfvars`)
```hcl
# dev.tfvars
environments = {
  dev = {
    region             = "us-east-1"
    eks_node_count     = 2
    eks_instance_type  = "t3.medium"
    rds_instance_class = "db.t3.micro"
    rds_multi_az       = false
    rds_encrypted      = false
    s3_enable_crr      = false
    iam_use_oidc       = false
    https_use_cf       = false
  }
}

# prod.tfvars
environments = {
  prod = {
    region             = "us-west-2"
    eks_node_count     = 4
    eks_instance_type  = "t3.large"
    rds_instance_class = "db.t3.medium"
    rds_multi_az       = true
    rds_encrypted      = true
    s3_enable_crr      = true
    iam_use_oidc       = true
    https_use_cf       = true
  }
}
```

### 🧩 Parameterized Module (`modules/environment/main.tf`)
```hcl
variable "env_name"           { type = string }
variable "region"             { type = string }
variable "eks_node_count"     { type = number }
variable "eks_instance_type"  { type = string }
variable "rds_instance_class" { type = string }
variable "rds_multi_az"       { type = bool }
variable "rds_encrypted"      { type = bool }
variable "s3_enable_crr"      { type = bool }
variable "iam_use_oidc"       { type = bool }
variable "https_use_cf"       { type = bool }
variable "db_secret"          { type = string }
variable "vpc_id"             { type = string }
variable "private_subnet_ids" { type = list(string) }
variable "cluster_role_arn"   { type = string }
variable "node_role_arn"      { type = string }
variable "acm_arn"            { type = string }

locals {
  is_prod = var.env_name == "prod"
}

# 1. S3 Bucket
resource "aws_s3_bucket" "assets" {
  bucket = "app-assets-${var.env_name}-${var.region}"
  tags   = { Environment = var.env_name }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_replication_configuration" "prod_crr" {
  count  = var.s3_enable_crr ? 1 : 0
  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.s3_crr.arn

  rule {
    id     = "replicate-to-us-west-2"
    status = "Enabled"
    destination {
      bucket = "arn:aws:s3:::app-assets-${var.env_name}-replica-us-west-2"
      region = "us-west-2"
    }
  }
}

resource "aws_iam_role" "s3_crr" {
  count  = var.s3_enable_crr ? 1 : 0
  name   = "s3-crr-role-${var.env_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{ Effect = "Allow", Principal = { Service = "s3.amazonaws.com" }, Action = "sts:AssumeRole" }]
  })
}

# 2. RDS PostgreSQL
resource "aws_db_subnet_group" "this" {
  name       = "app-rds-${var.env_name}"
  subnet_ids = var.private_subnet_ids
}

resource "aws_db_instance" "postgres" {
  identifier           = "app-postgres-${var.env_name}"
  engine               = "postgres"
  instance_class       = var.rds_instance_class
  allocated_storage    = local.is_prod ? 100 : 20
  db_name              = "appdb"
  username             = "admin"
  password             = var.db_secret
  skip_final_snapshot  = true
  deletion_protection  = true
  backup_retention_period = local.is_prod ? 14 : 7
  multi_az             = var.rds_multi_az
  storage_encrypted    = var.rds_encrypted
  publicly_accessible  = false
  db_subnet_group_name = aws_db_subnet_group.this.name
  # vpc_security_group_ids = [var.rds_sg_id] # Pass from root
}

# 3. EKS Cluster + Managed Node Group
resource "aws_eks_cluster" "this" {
  name     = "app-cluster-${var.env_name}"
  role_arn = var.cluster_role_arn
  vpc_config {
    subnet_ids = var.private_subnet_ids
  }
}

resource "aws_eks_node_group" "this" {
  cluster_name    = aws_eks_cluster.this.name
  node_group_name = "managed-${var.env_name}"
  node_role_arn   = var.node_role_arn
  instance_types  = [var.eks_instance_type]
  scaling_config {
    desired_size = var.eks_node_count
    min_size     = 1
    max_size     = var.eks_node_count
  }
  subnet_ids = var.private_subnet_ids
}

# 4. IAM (Dev: Programmatic User | Prod: OIDC Trust)
resource "aws_iam_user" "dev" {
  count = var.iam_use_oidc ? 0 : 1
  name  = "app-service-user-${var.env_name}"
}

resource "aws_iam_role" "service" {
  name = "app-service-role-${var.env_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = var.iam_use_oidc ? {
        Federated = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${replace(aws_eks_cluster.this.identity[0].oidc[0].issuer, "https://", "")}"
      } : { AWS = aws_iam_user.dev[0].arn }
      Action = "sts:AssumeRole"
      Condition = var.iam_use_oidc ? {
        StringEquals = { "${aws_eks_cluster.this.identity[0].oidc[0].issuer}:sub
